sys_script_include.script:
var HSBCTradeCaseCreation = Class.create();
HSBCTradeCaseCreation.prototype = {
    initialize: function() {},
    job_trigger: function() {
        var objectID = '';
        var newobjectid = '';
        var tmatFlag = false;

		//MSSOTIQUBE-1331, setting this flag as true because if counterpartycode is not provided, case should be created.
        var isClientandProcessLive = true;
        var getCaseSuppressionLogicLiveCheck = gs.getProperty('x_hsb11_hsbc_mss_t.case_suppressionlogic_isactive'); // Checking if case suppression logic value

        //Querying the business process instance table(MSSOTIQUBE-1096)
        var bpInstance = new GlideRecord("x_hsb11_hsbc_mss_o_business_process_instance");
        var sysTime = new GlideDateTime();
        bpInstance.addQuery("is_case_created", false);
        bpInstance.addQuery("is_exception", false);
        bpInstance.addQuery("expected_transition_time", "<", sysTime);
        bpInstance.addQuery("expected_transition_time", ">", getSuppressionUpdatedValue());
        //Logic for terminal stage
        bpInstance.addQuery("status.terminal_stage", 'false');

        //Additional code added for case suppression logic check for status isLive check
        if (getCaseSuppressionLogicLiveCheck == 'true')
            bpInstance.addQuery("status.is_live", 'true');

        bpInstance.query(); //Query the table

        // Process each record
        while (bpInstance.next()) {
            //logic for TMAT suppression
            if (bpInstance.status.ctac_code == "TMAT") {
                tmatFlag = validateTMAT(bpInstance.financial_object_id);
            } else {
                tmatFlag = false;

            }

            //MSSOTIQUBE-1331 - Stop Case Creation for Not Live Client
            var additionalAttribute = JSON.parse(bpInstance.additional_attributes);
            if (additionalAttribute.COUNTERPARTY_CODE != null) {
                isClientandProcessLive = checkClientandProcessLive(additionalAttribute.COUNTERPARTY_CODE, bpInstance.business_process_definition);
            }else{
				gs.error("CounterParty Code not provided for : "+ bpInstance.financial_object_record.getDisplayValue());
			}

            if (isClientandProcessLive == false) {
                try {
                    bpInstance.expected_transition_time = "";
                    bpInstance.update();
                } catch (e) {
                    gs.error("Unexpected error occurred during processing: " + "Name: " + e.name + "  " + "Message: " + e.message); //MSSOTIQUBE-1331
                }
            }
            //Adding additional check so we check condition for real time values when this while loop is running
            else if (bpInstance.expected_transition_time < sysTime && bpInstance.is_exception == false && tmatFlag == false) {
                //MSSOTIQUBE-1096
                try {
                    // Prepare the trade case record(MSSOTIQUBE-1096)
                    var tradeCase = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
                    tradeCase.initialize();

                    //Retrieve the automation group id(MSSOTIQUBE-1096)
                    var mssSNAutomationGrpID = gs.getProperty("HSBC_MOCS_Group");
                    tradeCase.setValue("assignment_group", mssSNAutomationGrpID);

                    // Populate the trade case field
                    tradeCase.short_description = "Time Limit Exceeded at " + bpInstance.expected_transition_time.getDisplayValue();
                    objectID = bpInstance.financial_object_record.getDisplayValue();
                    tradeCase.financial_object.setDisplayValue(objectID);
                    tradeCase.trade_status = bpInstance.status;
                    tradeCase.u_fo_process_status = bpInstance.status;
                    tradeCase.u_additional_attributes = bpInstance.additional_attributes;
                    tradeCase.u_objectversion = bpInstance.object_version;
                    tradeCase.u_event_type = bpInstance.event_type;
                    tradeCase.u_objectidtype = bpInstance.objectid_type;
                    tradeCase.u_object_type = bpInstance.object_type;
                    var bpiValue = bpInstance.number.getDisplayValue();
                    tradeCase.u_business_process_instance.setDisplayValue(bpiValue);
                    tradeCase.u_message_id = bpInstance.messageid;
                    tradeCase.u_source = bpInstance.source;

                    // Insert the trade case record and update business process instance(MSSOTIQUBE-1096)
                    newobjectid = tradeCase.insert();
                    bpInstance.is_case_created = true;
                    bpInstance.payload = tradeCase.u_payload;
                    bpInstance.update();
                } catch (e) {
                    gs.error("Unexpected error occurred during processing: " + "Name: " + e.name + "  " + "Message: " + e.message); //MSSOTIQUBE-1096
                }

            }
        }
        // Function to get the updated suppression value
        function getSuppressionUpdatedValue() {
            var getSuppUpdatedValue = new GlideRecord('sys_properties');
            getSuppUpdatedValue.get('name', 'x_hsb11_hsbc_mss_t.case_suppressionlogic_isactive');
            return getSuppUpdatedValue.sys_updated_on;
        }

        // Function to validate TMAT logic
        function validateTMAT(trade_id) {
            var allocs = new GlideRecord('sn_bom_trade');
            allocs.addQuery("u_ctac_trade_did", trade_id);
            allocs.addQuery("u_trade_status.ctac_code", "AMSM");
            allocs.query();
            while (allocs.next()) {
                var amsmCases = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
                amsmCases.addQuery("financial_object", allocs.sys_id);
                amsmCases.addQuery("state", "!=", 7);
                amsmCases.addQuery("state", "!=", 3);
                amsmCases.addQuery("state", "!=", 4);
                amsmCases.query();
                if (amsmCases.next()) {
                    return true;
                }
            }
            return false;
        }

        function checkClientandProcessLive(counterPartyCode, businessProcessDefinition) {
            var checkClientLive = new GlideRecord('x_hsb11_hsbc_mss_o_client_and_processes_checklist');
            checkClientLive.addEncodedQuery('client.u_counterparty_code=' + counterPartyCode + '^business_process_definition=' + businessProcessDefinition);
            checkClientLive.query();
            if (checkClientLive.next()) {
                return checkClientLive.active;
            } else {
                return false;
            }
        }

    },
    type: 'HSBCTradeCaseCreation'
};
